      "keystrokes": "cat > /tmp/layout_test.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define V 50257
#define M 50000
#define D 768
#define L 12
#define H 12
float*W;long WN;
unsigned char tb[4000000];int to[V],tl[V],np1[M],np2[M];
#define HN 131072
int ht[HN],b2u[256],u2b[512];
unsigned Hh(unsigned char*s,int n){unsigned h=2166136261;for(int i=0;i<n;i++){h^=s[i];h*=16777619;}return h;}
int find(unsigned char*s,int n){unsigned h=Hh(s,n);for(int i=h%HN;;i=(i+1)%HN){if(!ht[i])return-1;int id=ht[i]-1;if(tl[id]==n&&!memcmp(tb+to[id],s,n))return id;}}
void add(int id){unsigned h=Hh(tb+to[id],tl[id]);for(int i=h%HN;;i=(i+1)%HN)if(!ht[i]){ht[i]=id+1;return;}}
void initb(){int j=0;for(int i=0;i<256;i++)b2u[i]=-1;for(int i=33;i<127;i++)b2u[i]=i;for(int i=161;i<173;i++)b2u[i]=i;for(int i=174;i<256;i++)b2u[i]=i;for(int i=0;i<256;i++)if(b2u[i]<0)b2u[i]=256+j++;for(int i=0;i<256;i++)u2b[b2u[i]]=i;}
void loadbpe(char*fn){initb();int p=0;for(int i=0;i<256;i++){to[i]=p;tb[p++]=i;tl[i]=1;add(i);}FILE*f=fopen(fn,"rb");char ln[512];fgets(ln,512,f);for(int r=0;r<M;r++){fgets(ln,512,f);int sp=0;while(ln[sp]!=' ')sp++;unsigned char b[64];int n=0;for(int i=0;i<sp;){int c=ln[i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[i+1]&63)];i+=2;}}int id1=find(b,n);n=0;int l2=strlen(ln+sp+1)-1;for(int i=0;i<l2;){int c=ln[sp+1+i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[sp+1+i+1]&63)];i+=2;}}int id2=find(b,n);int id=256+r;to[id]=p;memcpy(tb+p,tb+to[id1],tl[id1]);p+=tl[id1];memcpy(tb+p,tb+to[id2],tl[id2]);p+=tl[id2];tl[id]=p-to[id];add(id);np1[r]=id1;np2[r]=id2;}fclose(f);}
int tok(char*s,int*tk){int n=0,len=strlen(s);for(int i=0;i<len;){int st=i;while(i<len&&s[i]==' ')i++;while(i<len&&s[i]!=' ')i++;int wt[128],wn=0;for(int j=st;j<i;j++)wt[wn++]=b2u[(unsigned char)s[j]];while(wn>1){int best=-1,bestr=M;for(int a=0;a<wn-1;a++){int r=0;while(r<M&&!(np1[r]==wt[a]&&np2[r]==wt[a+1]))r++;if(r<M&&r<bestr){bestr=r;best=a;}}if(best<0)break;wt[best]=256+bestr;for(int b=best+1;b<wn-1;b++)wt[b]=wt[b+1];wn--;}for(int j=0;j<wn;j++)tk[n++]=wt[j];}return n;}
void ln(float*o,float*x,float*g,float*b){float m=0,v=0;for(int i=0;i<D;i++)m+=x[i];m/=D;for(int i=0;i<D;i++){float d=x[i]-m;v+=d*d;}v/=D;float s=1.0f/sqrtf(v+1e-5f);for(int i=0;i<D;i++)o[i]=(x[i]-m)*s*(g[i]+1)+b[i];}
float ge(float x){return 0.5f*x*(1.0f+erff(x*0.70710678f));}
void fwd(int*T,int Tn,int trans,int wtefirst,float*lgs){
 static float x[256][D],h[256][D],q[256][D],k[256][D],v[256][D],at[256][D],qk[2304],h1[3072],tm[D];
 long wte,wpe,lfg,lfb,nb[12];
 long bl[12]={0,7087872,14175744,21263616,28351488,35439360,42527232,49615104,56702976,63790848,70878720,77966592};
 long o1g,o1b,aw,ab,pw,pb,g2,b2,fw,fb,p2w,p2b;
 if(wtefirst){wte=0;wpe=38597376;lfg=WN-1536;lfb=WN-768;for(int i=0;i<12;i++)nb[i]=39383808+i*7087872;o1g=0;o1b=768;aw=1536;ab=1771008;pw=1773312;pb=2363136;g2=2363904;b2=2364672;fw=2365440;fb=4724736;p2w=4727808;p2b=7087104;}
 else{int bn[12]={0,1,10,11,2,3,4,5,6,7,8,9};for(int i=0;i<12;i++)nb[bn[i]]=bl[i];wte=WN-38597376;wpe=WN-38597376-786432;lfg=WN-38597376-786432-768;lfb=WN-38597376-786432-1536;o1g=2363136;o1b=2362368;aw=2304;ab=0;pw=1772544;pb=1771776;g2=2364672;b2=2363904;fw=2368512;fb=2365440;p2w=4728576;p2b=4727808;}
 for(int t=0;t<Tn;t++)for(int i=0;i<D;i++)x[t][i]=W[wte+T[t]*D+i]+W[wpe+t*D+i];
 for(int l=0;l<L;l++){long b=nb[l];
  for(int t=0;t<Tn;t++)ln(h[t],x[t],W+b+o1g,W+b+o1b);
  for(int t=0;t<Tn;t++){for(int j=0;j<2304;j++){float s=W[b+ab+j];for(int i=0;i<D;i++)s+=h[t][i]*W[b+aw+(trans?j*D+i:i*2304+j)];qk[j]=s;}memcpy(q[t],qk,D*4);memcpy(k[t],qk+D,D*4);memcpy(v[t],qk+2*D,D*4);}
  for(int hi=0;hi<H;hi++)for(int t=0;t<Tn;t++){float sc[256];for(int t2=0;t2<=t;t2++){float s=0;for(int d=0;d<64;d++)s+=q[t][hi*64+d]*k[t2][hi*64+d];sc[t2]=s*0.125f;}float mx=sc[0];for(int t2=1;t2<=t;t2++)if(sc[t2]>mx)mx=sc[t2];float sm=0;for(int t2=0;t2<=t;t2++){sc[t2]=expf(sc[t2]-mx);sm+=sc[t2];}for(int t2=0;t2<=t;t2++)sc[t2]/=sm;for(int d=0;d<64;d++){float s=0;for(int t2=0;t2<=t;t2++)s+=sc[t2]*v[t2][hi*64+d];at[t][hi*64+d]=s;}}
  for(int t=0;t<Tn;t++){for(int j=0;j<D;j++){float s=W[b+pb+j];for(int i=0;i<D;i++)s+=at[t][i]*W[b+pw+(trans?j*D+i:i*D+j)];tm[j]=s;}for(int i=0;i<D;i++)x[t][i]+=tm[i];}
  for(int t=0;t<Tn;t++){ln(h[t],x[t],W+b+g2,W+b+b2);for(int j=0;j<3072;j++){float s=W[b+fb+j];for(int i=0;i<D;i++)s+=h[t][i]*W[b+fw+(trans?j*D+i:i*3072+j)];h1[j]=ge(s);}for(int j=0;j<D;j++){float s=W[b+p2b+j];for(int i=0;i<3072;i++)s+=h1[i]*W[b+p2w+(trans?j*3072+i:i*D+j)];tm[j]=s;}for(int i=0;i<D;i++)x[t][i]+=tm[i];}}
 ln(tm,x[Tn-1],W+lfg,W+lfb);
 for(int i=0;i<V;i++){float s=0;for(int j=0;j<D;j++)s+=tm[j]*W[wte+i*D+j];lgs[i]=s;}}
int main(int c,char**a){FILE*f=fopen(a[1],"rb");fseek(f,0,SEEK_END);WN=ftell(f)/4;fseek(f,0,SEEK_SET);W=malloc(WN*4);if(fread(W,4,WN,f)!=WN)return 1;fclose(f);loadbpe(a[2]);
 static int tk[256];int T=tok(a[3],tk);printf("Tokens:");for(int i=0;i<T;i++)printf(" %d",tk[i]);printf("\n");
 static float lgs[V];const char*cn[]={"wte-cr0","wte-cr1","blk-al0","blk-al1"};int cfg[4][2]={{1,0},{1,1},{0,0},{0,1}};
 for(int ci=0;ci<4;ci++){int p[]={464};fwd(p,1,cfg[ci][1],cfg[ci][0],lgs);printf("%s The:",cn[ci]);for(int r=0;r<3;r++){int b=0;for(int i=1;i<V;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.1f)",b,lgs[b]);lgs[b]=-1e9;}printf("\n");}
 for(int ci=0;ci<4;ci++){static int gt[256]={464,2068,7546,21831};int G=4;printf("%s Gen:",cn[ci]);for(int i=0;i<10;i++){fwd(gt,G,cfg[ci][1],cfg[ci][0],lgs);int b=0;for(int j=1;j<V;j++)if(lgs[j]>lgs[b])b=j;printf(" %d",b);gt[G++]=b;}printf("\n");}
 return 0;}
